import glob, flowio, os

for f in sorted(glob.glob(\"/task/input/fcs/*.fcs\")):
    fd = flowio.FlowData(f)
    text = fd.text
    # look for voltage keywords
    voltages = {}
    for k, v in text.items():
        if \"v\" in k.lower() or \"volt\" in k.lower() or k.startswith(\"\\$P\") and k.endswith(\"V\"):
