    time = text.get(\"\\$BTIM\", \"\") + \" - \" + text.get(\"\\$ETIM\", \"\")
    spill = [k for k in text.keys() if \"spill\" in k.lower() or \"comp\" in k.lower()]
    print(os.path.basename(f), \"time:\", time, \"spill_keys:\", spill)
'
